import { uniqueStrings } from './unique_repeat.mjs';
import assert from 'node:assert';

// Basic dedup preserving order
assert.deepStrictEqual(uniqueStrings(['a','b','a','c','b']), ['a','b','c']);

// Case-sensitive: upper/lower distinct
assert.deepStrictEqual(uniqueStrings(['A','a','A','a']), ['A','a']);

// Whitespace not trimmed
assert.deepStrictEqual(uniqueStrings([' x','x',' x']), [' x','x']);

// Original spelling preserved
assert.deepStrictEqual(uniqueStrings(['foo','FOO','foo']), ['foo','FOO']);

// Empty input
assert.deepStrictEqual(uniqueStrings([]), []);

// Input not mutated
const input = ['a','b','a'];
const snapshot = [...input];
uniqueStrings(input);
assert.deepStrictEqual(input, snapshot);

// Returns a new array (not same reference)
const out = uniqueStrings(['a','a']);
assert.notStrictEqual(out, ['a','a']);

